// Multi-Band Excitation voice decoder — a port of mbelib 1.3.0 (szechyjs/mbelib,
// ISC licence; see tables.ts for the notice). Two codecs share one synthesiser:
//
//   · IMBE 7200x4400  — P25 Phase 1 FDMA voice (88 information bits / 20 ms)
//   · AMBE+2 3600x2450 — P25 Phase 2 TDMA voice (49 information bits / 20 ms),
//                        also DMR/NXDN's half-rate vocoder
//
// This file takes the *information* bits (after FEC — see dsp/p25/fec.ts and the
// P25 framers) and turns each 20 ms frame into 160 samples at 8 kHz. It is a
// line-by-line port of mbelib.c, imbe7200x4400.c (mbe_decodeImbe4400Parms,
// mbe_processImbe4400Dataf) and ambe3600x2450.c (mbe_decodeAmbe2450Parms,
// mbe_processAmbe2450Dataf); the function names are kept so the two can be read
// side by side. Verified against the compiled C library's own output in
// web/test/mbe.test.ts (fixtures/mbe-ref, generated by refgen.cpp there).
//
// Two profiles (`MbeDecoder` option `profile`):
//   · "mbelib"   — the C library's behaviour exactly; what web/test/mbe.test.ts
//                  checks frame for frame against the compiled reference.
//   · "enhanced" (default) — the decoding and synthesis improvements Trunk
//                  Recorder made to OP25's float IMBE decoder (commit 1aac86c,
//                  docs/Notes/VOCODER-IMPROVEMENTS.md there), carried over to
//                  mbelib's synthesis:
//       - TIA-102.BABA-A §7.7/§7.8 error concealment (smoothed error rate,
//         repeat on E0 ≥ 3 — not TIA's 2: Golay(23,12) corrects three — or
//         ET ≥ 10 + 40·ER, mute past 4 repeats or ER > 0.0875) instead of
//         mbelib's "errs2 > 5";
//       - mutes FADE: a zero-amplitude frame holding the last good parameters,
//         prediction memory kept, instead of hard silence + a full reset;
//       - envelope phase on voiced harmonics (US5701390: a discrete Hilbert
//         transform of the log amplitudes, i.e. minimum phase) with TIA's
//         random phase weighted by the unvoiced fraction, instead of pure
//         linear phase (a buzzy, too-sharp pulse train);
//       - every voiced harmonic GLIDES between frames (linear amplitude,
//         quadratic phase) when the pitch moves < 20 %, instead of being
//         cross-faded as two sinusoids (beaded upper harmonics);
//       - a +3 dB presence lift from 2.2 kHz to 3.7 kHz.
//     Not carried over, because mbelib already does it or never had the bug:
//     the unprotected-bits shift (our IMBE bits are verified against mbelib),
//     a per-frame S_E (mbelib has no adaptive smoothing), the short-period
//     noise generator (the RNG here is Math.random), smooth unvoiced
//     synthesis (mbelib's windows already cross-fade over the whole frame),
//     and the Phase 2 level fix (it corrects OP25's float synthesiser's
//     scale, not mbelib's).
//
// Deliberate differences from the C:
//   · `rand()` is injectable (default Math.random) so the test can replay the
//     C library's random sequence exactly — mbelib seeds its unvoiced-band noise
//     and phase jitter from it.
//   · Arithmetic is double, not float. The reference test therefore compares
//     with a tolerance, not bit-exactly.
//   · Output is float in [-1, 1] (mbelib's short output is float × 7, clipped at
//     ±32760 — `mbeToUnit` applies the same gain and clip, then divides by 32768).

import {
  AmbeDg,
  AmbeHOCb5,
  AmbeHOCb6,
  AmbeHOCb7,
  AmbeHOCb8,
  AmbeLmprbl,
  AmbeLtable,
  AmbePRBA24,
  AmbePRBA58,
  AmbeVuv,
  AmbeW0table,
  B2,
  ba,
  bo,
  hoba,
  ImbeJi,
  quantstep,
  standdev,
  Ws,
} from "./tables.ts";

/** Samples per 20 ms frame at 8 kHz. */
export const MBE_FRAME_SAMPLES = 160;
export const MBE_SAMPLE_RATE = 8000;

// Arrays are one longer than mbelib's [57]: the IMBE/AMBE prediction reads
// log2Ml[intkl + 1], which reaches index 57 when the previous frame had L = 56
// (undefined behaviour in the C, a read of the next struct field). Here it reads 0.
const NL = 58;

export interface MbeParms {
  w0: number;
  L: number;
  K: number;
  Vl: Int8Array;
  Ml: Float64Array;
  log2Ml: Float64Array;
  PHIl: Float64Array;
  PSIl: Float64Array;
  gamma: number;
  repeat: number;
}

export function newMbeParms(): MbeParms {
  return {
    w0: 0,
    L: 0,
    K: 0,
    Vl: new Int8Array(NL),
    Ml: new Float64Array(NL),
    log2Ml: new Float64Array(NL),
    PHIl: new Float64Array(NL),
    PSIl: new Float64Array(NL),
    gamma: 0,
    repeat: 0,
  };
}

/** A source of uniform floats in [0, 1]. mbelib's `(float)rand()/RAND_MAX`. */
export type MbeRng = () => number;

export function mbe_moveMbeParms(cur: MbeParms, prev: MbeParms): void {
  prev.w0 = cur.w0;
  prev.L = cur.L;
  prev.K = cur.K;
  prev.Ml[0] = 0;
  prev.gamma = cur.gamma;
  prev.repeat = cur.repeat;
  for (let l = 0; l <= 56; l++) {
    prev.Ml[l] = cur.Ml[l];
    prev.Vl[l] = cur.Vl[l];
    prev.log2Ml[l] = cur.log2Ml[l];
    prev.PHIl[l] = cur.PHIl[l];
    prev.PSIl[l] = cur.PSIl[l];
  }
}

export function mbe_useLastMbeParms(cur: MbeParms, prev: MbeParms): void {
  cur.w0 = prev.w0;
  cur.L = prev.L;
  cur.K = prev.K;
  cur.Ml[0] = 0;
  cur.gamma = prev.gamma;
  cur.repeat = prev.repeat;
  for (let l = 0; l <= 56; l++) {
    cur.Ml[l] = prev.Ml[l];
    cur.Vl[l] = prev.Vl[l];
    cur.log2Ml[l] = prev.log2Ml[l];
    cur.PHIl[l] = prev.PHIl[l];
    cur.PSIl[l] = prev.PSIl[l];
  }
}

export function mbe_initMbeParms(cur: MbeParms, prev: MbeParms, prevEnh: MbeParms): void {
  prev.w0 = 0.09378;
  prev.L = 30;
  prev.K = 10;
  prev.gamma = 0;
  for (let l = 0; l <= 56; l++) {
    prev.Ml[l] = 0;
    prev.Vl[l] = 0;
    prev.log2Ml[l] = 0; // log2 of 1 == 0
    prev.PHIl[l] = 0;
    prev.PSIl[l] = Math.PI / 2;
  }
  prev.repeat = 0;
  mbe_moveMbeParms(prev, cur);
  mbe_moveMbeParms(prev, prevEnh);
}

export function mbe_spectralAmpEnhance(cur: MbeParms): void {
  const Wl = new Float64Array(NL);
  let Rm0 = 0;
  let Rm1 = 0;
  for (let l = 1; l <= cur.L; l++) {
    Rm0 += cur.Ml[l] * cur.Ml[l];
    Rm1 += cur.Ml[l] * cur.Ml[l] * Math.cos(cur.w0 * l);
  }
  const R2m0 = Rm0 * Rm0;
  const R2m1 = Rm1 * Rm1;
  for (let l = 1; l <= cur.L; l++) {
    if (cur.Ml[l] !== 0) {
      Wl[l] =
        Math.sqrt(cur.Ml[l]) *
        Math.pow(
          (0.96 * Math.PI * (R2m0 + R2m1 - 2 * Rm0 * Rm1 * Math.cos(cur.w0 * l))) / (cur.w0 * Rm0 * (R2m0 - R2m1)),
          0.25,
        );
      if (8 * l <= cur.L) {
        // untouched
      } else if (Wl[l] > 1.2) {
        cur.Ml[l] = 1.2 * cur.Ml[l];
      } else if (Wl[l] < 0.5) {
        cur.Ml[l] = 0.5 * cur.Ml[l];
      } else {
        cur.Ml[l] = Wl[l] * cur.Ml[l];
      }
    }
  }
  // scaling factor
  let sum = 0;
  for (let l = 1; l <= cur.L; l++) {
    const M = Math.abs(cur.Ml[l]);
    sum += M * M;
  }
  const gamma = sum === 0 ? 1 : Math.sqrt(Rm0 / sum);
  for (let l = 1; l <= cur.L; l++) cur.Ml[l] = gamma * cur.Ml[l];
}

/** The synthesis improvements ("enhanced" profile); null = mbelib exactly. */
export interface MbeSynthOpts {
  /** Envelope-phase strength (Trunk Recorder phase_c_env). */
  cEnv: number;
  /** Envelope-phase weight on harmonics ≤ L/4 (phase_low_blend). */
  lowBlend: number;
  /** Random phase on upper harmonics × unvoiced fraction (phase_w_rand). */
  wRand: number;
  /** Hilbert kernel half-length (phase_kernel_d) and log-envelope decay past L (phase_kernel_gamma). */
  kernelD: number;
  kernelGamma: number;
  /** Glide voiced harmonics when |Δw0| < tol·w0 (interp_pitch_tol). */
  interpTol: number;
  /** Presence lift, dB at 3.7 kHz, starting at f1 Hz (hf_lift_db / hf_lift_f1). */
  hfLiftDb: number;
  hfLiftF1: number;
}

export const ENHANCED_SYNTH: MbeSynthOpts = {
  cEnv: 0.7,
  lowBlend: 0.4,
  wRand: 0.25,
  kernelD: 19,
  kernelGamma: 0.6,
  interpTol: 0.2,
  hfLiftDb: 3,
  hfLiftF1: 2200,
};

/** Presence-lift gain for a component at w radians/sample (8 kHz). */
function hfGain(w: number, o: MbeSynthOpts): number {
  if (o.hfLiftDb === 0) return 1;
  const f = (w * 8000) / (2 * Math.PI);
  if (f <= o.hfLiftF1) return 1;
  const t = Math.min(1, (f - o.hfLiftF1) / (3700 - o.hfLiftF1));
  return Math.pow(10, (o.hfLiftDb * t) / 20);
}

/**
 * Envelope phase per harmonic (Trunk Recorder compute_envelope_phases, after
 * US5701390): the odd-only discrete Hilbert kernel 2/(πm) over the
 * mean-removed log2 amplitudes, extended past L by geometric decay and
 * reflected below 1 — the minimum-phase response of the spectral envelope.
 */
function envelopePhase(mp: MbeParms, maxl: number, o: MbeSynthOpts): Float64Array {
  const D = Math.min(19, o.kernelD);
  const OFF = D;
  const B = new Float64Array(57 + 2 * D + 2);
  const L = mp.L;
  let mean = 0;
  for (let l = 1; l <= L; l++) {
    const m = mp.Ml[l];
    const b = m > 1e-6 ? Math.log2(m) : -20;
    B[l + OFF] = b;
    mean += b;
  }
  if (L > 0) {
    mean /= L;
    for (let l = 1; l <= L; l++) B[l + OFF] -= mean;
  }
  let decay = 1;
  const BL = B[L + OFF];
  for (let l = L + 1; l <= L + D && l + OFF < B.length; l++) {
    decay *= o.kernelGamma;
    B[l + OFF] = BL * decay;
  }
  for (let l = 1; l <= D; l++) B[-l + OFF] = B[l + OFF];
  const env = new Float64Array(58);
  for (let ell = 1; ell <= maxl; ell++) {
    let e = 0;
    for (let m = 1; m <= D; m += 2) {
      const hi = ell + m + OFF;
      e += ((2 / Math.PI) * ((hi < B.length ? B[hi] : 0) - B[ell - m + OFF])) / m;
    }
    env[ell] = e;
  }
  return env;
}

export function mbe_synthesizeSilencef(out: Float32Array): void {
  out.fill(0);
}

export function mbe_synthesizeSpeechf(
  out: Float32Array,
  cur: MbeParms,
  prev: MbeParms,
  uvquality: number,
  rand: MbeRng,
  opts: MbeSynthOpts | null = null,
): void {
  const N = 160;
  const randPhase = () => rand() * (Math.PI * 2) - Math.PI;
  const uvthresholdf = 2700;
  const uvthreshold = (uvthresholdf * Math.PI) / 4000;
  // voiced/unvoiced/gain settings
  const uvsine = 1.3591409 * Math.E;
  const uvrand = 2.0;
  if (uvquality < 1 || uvquality > 64) uvquality = 3;
  const loguvquality = uvquality === 1 ? 1 / Math.E : Math.log(uvquality) / uvquality;
  const uvstep = 1.0 / uvquality;
  const qfactor = loguvquality;
  const uvoffset = (uvstep * (uvquality - 1)) / 2;

  let numUv = 0;
  for (let l = 1; l <= cur.L; l++) if (cur.Vl[l] === 0) numUv++;

  const cw0 = cur.w0;
  const pw0 = prev.w0;
  out.fill(0);

  // eq 128 and 129
  let maxl: number;
  if (cur.L > prev.L) {
    maxl = cur.L;
    for (let l = prev.L + 1; l <= maxl; l++) {
      prev.Ml[l] = 0;
      prev.Vl[l] = 1;
    }
  } else {
    maxl = prev.L;
    for (let l = cur.L + 1; l <= maxl; l++) {
      cur.Ml[l] = 0;
      cur.Vl[l] = 1;
    }
  }

  // update phil from eq 139,140
  const env = opts ? envelopePhase(cur, maxl, opts) : null;
  const rho = cur.L > 0 ? numUv / cur.L : 0;
  for (let l = 1; l <= 56; l++) {
    cur.PSIl[l] = prev.PSIl[l] + (pw0 + cw0) * ((l * N) / 2);
    if (env && opts) {
      // Envelope phase (Trunk Recorder): weighted down on the low harmonics,
      // which carry the glottal-pulse alignment; TIA's random term, scaled by
      // the unvoiced fraction, on the rest.
      if (l <= Math.trunc(cur.L / 4)) cur.PHIl[l] = cur.PSIl[l] + opts.lowBlend * opts.cEnv * env[l];
      else cur.PHIl[l] = cur.PSIl[l] + opts.cEnv * env[l] + opts.wRand * rho * randPhase();
    } else if (l <= Math.trunc(cur.L / 4)) {
      cur.PHIl[l] = cur.PSIl[l];
    } else {
      cur.PHIl[l] = cur.PSIl[l] + (numUv * randPhase()) / cur.L;
    }
  }

  // Amplitudes as synthesised (the parameter sets keep the decoded ones):
  // with the presence lift applied at each component's frequency.
  const mNew = new Float64Array(NL);
  const mOld = new Float64Array(NL);
  for (let l = 1; l <= maxl; l++) {
    mNew[l] = cur.Ml[l] * (opts ? hfGain(cw0 * l, opts) : 1);
    mOld[l] = prev.Ml[l] * (opts ? hfGain(pw0 * l, opts) : 1);
  }

  const rphase = new Float64Array(64);
  const rphase2 = new Float64Array(64);
  for (let l = 1; l <= maxl; l++) {
    const cw0l = cw0 * l;
    const pw0l = pw0 * l;
    if (cur.Vl[l] === 0 && prev.Vl[l] === 1) {
      for (let i = 0; i < uvquality; i++) rphase[i] = randPhase();
      for (let n = 0; n < N; n++) {
        // eq 131
        const C1 = Ws[n + N] * mOld[l] * Math.cos(pw0l * n + prev.PHIl[l]);
        let C3 = 0;
        for (let i = 0; i < uvquality; i++) {
          C3 += Math.cos(cw0 * n * (l + i * uvstep - uvoffset) + rphase[i]);
          if (cw0l > uvthreshold) C3 += (cw0l - uvthreshold) * uvrand * rand();
        }
        C3 = C3 * uvsine * Ws[n] * mNew[l] * qfactor;
        out[n] += C1 + C3;
      }
    } else if (cur.Vl[l] === 1 && prev.Vl[l] === 0) {
      for (let i = 0; i < uvquality; i++) rphase[i] = randPhase();
      for (let n = 0; n < N; n++) {
        // eq 132
        const C1 = Ws[n] * mNew[l] * Math.cos(cw0l * (n - N) + cur.PHIl[l]);
        let C3 = 0;
        for (let i = 0; i < uvquality; i++) {
          C3 += Math.cos(pw0 * n * (l + i * uvstep - uvoffset) + rphase[i]);
          if (pw0l > uvthreshold) C3 += (pw0l - uvthreshold) * uvrand * rand();
        }
        C3 = C3 * uvsine * Ws[n + N] * mOld[l] * qfactor;
        out[n] += C1 + C3;
      }
    } else if (cur.Vl[l] === 1 || prev.Vl[l] === 1) {
      if (opts && Math.abs(cw0 - pw0) < opts.interpTol * cw0) {
        // Glide (Trunk Recorder's widened TIA fine transition): amplitude
        // linear, frequency linear, phase quadratic from prev.PHIl at n = 0
        // to cur.PHIl at n = N. mbelib's Ws halves sum to exactly 1, so this
        // is level-matched to the cross-fade it replaces.
        let Dpl = cur.PHIl[l] - prev.PHIl[l] - (pw0 + cw0) * l * (N / 2);
        Dpl -= 2 * Math.PI * Math.floor((Dpl + Math.PI) / (2 * Math.PI));
        const THa = pw0l + Dpl / N;
        const THb = ((cw0 - pw0) * l) / (2 * N);
        const Mb = (mNew[l] - mOld[l]) / N;
        for (let n = 0; n < N; n++) out[n] += (mOld[l] + n * Mb) * Math.cos(prev.PHIl[l] + (THa + THb * n) * n);
      } else {
        for (let n = 0; n < N; n++) {
          // eq 133-1, 133-2
          const C1 = Ws[n + N] * mOld[l] * Math.cos(pw0l * n + prev.PHIl[l]);
          const C2 = Ws[n] * mNew[l] * Math.cos(cw0l * (n - N) + cur.PHIl[l]);
          out[n] += C1 + C2;
        }
      }
    } else {
      for (let i = 0; i < uvquality; i++) rphase[i] = randPhase();
      for (let i = 0; i < uvquality; i++) rphase2[i] = randPhase();
      for (let n = 0; n < N; n++) {
        let C3 = 0;
        for (let i = 0; i < uvquality; i++) {
          C3 += Math.cos(pw0 * n * (l + i * uvstep - uvoffset) + rphase[i]);
          if (pw0l > uvthreshold) C3 += (pw0l - uvthreshold) * uvrand * rand();
        }
        C3 = C3 * uvsine * Ws[n + N] * mOld[l] * qfactor;
        let C4 = 0;
        for (let i = 0; i < uvquality; i++) {
          C4 += Math.cos(cw0 * n * (l + i * uvstep - uvoffset) + rphase2[i]);
          if (cw0l > uvthreshold) C4 += (cw0l - uvthreshold) * uvrand * rand();
        }
        C4 = C4 * uvsine * Ws[n] * mNew[l] * qfactor;
        out[n] += C3 + C4;
      }
    }
  }
}

/** mbelib's float→short gain (×7, clipped at ±32760), scaled to [-1, 1]. */
export function mbeToUnit(buf: Float32Array): Float32Array {
  for (let i = 0; i < buf.length; i++) {
    let a = 7 * buf[i];
    if (a > 32760) a = 32760;
    else if (a < -32760) a = -32760;
    buf[i] = a / 32768;
  }
  return buf;
}

// ── IMBE 7200x4400 (P25 Phase 1) ─────────────────────────────────────────────

/** Returns 0 on a valid frame, 1 on an invalid pitch / L (mbelib's `bad`). */
export function mbe_decodeImbe4400Parms(imbe_d: ArrayLike<number>, cur: MbeParms, prev: MbeParms): number {
  const bb: Uint8Array[] = Array.from({ length: 58 }, () => new Uint8Array(12));
  const Cik: Float64Array[] = Array.from({ length: 7 }, () => new Float64Array(11));
  const Gm = new Float64Array(7);
  const Ri = new Float64Array(7);
  const Tl = new Float64Array(NL);
  const flokl = new Float64Array(NL);
  const deltal = new Float64Array(NL);
  const intkl = new Int32Array(NL);

  cur.repeat = prev.repeat;

  // fundamental frequency w0 from b0
  const b0 =
    (imbe_d[0] << 7) | (imbe_d[1] << 6) | (imbe_d[2] << 5) | (imbe_d[3] << 4) |
    (imbe_d[4] << 3) | (imbe_d[5] << 2) | (imbe_d[85] << 1) | imbe_d[86];
  if (b0 > 207) return 1; // 216..219 silence, the rest invalid — both "bad" to mbelib

  cur.w0 = (4 * Math.PI) / (b0 + 39.5);
  const L = Math.trunc(0.9254 * Math.trunc(Math.PI / cur.w0 + 0.25));
  if (L > 56 || L < 9) return 1;
  cur.L = L;
  const L9 = L - 9;
  const K = L < 37 ? Math.trunc((L + 2) / 3) : 12;
  cur.K = K;

  // read bits from imbe_d into b0..bL+1
  const boBase = L9 * 79 * 2;
  for (let i = 6, p = 0; i < 85; i++, p++) {
    bb[bo[boBase + 2 * p]][bo[boBase + 2 * p + 1]] = imbe_d[i];
  }

  // Vl
  let j = 1;
  let k = K - 1;
  for (let i = 1; i <= L; i++) {
    cur.Vl[i] = bb[1][k];
    if (j === 3) {
      j = 1;
      k = k > 0 ? k - 1 : 0;
    } else {
      j++;
    }
  }

  // G1 from b2
  const b2 = (bb[2][5] << 5) | (bb[2][4] << 4) | (bb[2][3] << 3) | (bb[2][2] << 2) | (bb[2][1] << 1) | bb[2][0];
  Gm[1] = B2[b2];

  // G2..G6 (from b3..b7), annex E, eq. 68
  const baBase = L9 * 5 * 2;
  for (let i = 2; i < 7; i++) {
    const ba1 = Math.trunc(ba[baBase + (i - 2) * 2]);
    const ba2 = ba[baBase + (i - 2) * 2 + 1];
    let bm = 0;
    for (let jj = ba1 - 1; jj >= 0; jj--) bm = (bm << 1) | bb[i + 1][jj];
    Gm[i] = ba2 * (bm - Math.pow(2, ba1 - 1) + 0.5);
  }

  // inverse DCT Gi → Ri
  for (let i = 1; i <= 6; i++) {
    let sum = 0;
    for (let m = 1; m <= 6; m++) {
      const am = m === 1 ? 1 : 2;
      sum += am * Gm[m] * Math.cos((Math.PI * (m - 1) * (i - 0.5)) / 6);
    }
    Ri[i] = sum;
  }

  // load b8..bL+1 into Ci,k
  let m = 8;
  for (let i = 1; i <= 6; i++) {
    Cik[i][1] = Ri[i];
    for (k = 2; k <= ImbeJi[L9 * 6 + i - 1]; k++) {
      const Bm = hoba[L9 * 50 + m - 8];
      if (Bm === 0) {
        Cik[i][k] = 0;
      } else {
        let bm = 0;
        for (let b = 0; b < Bm; b++) bm = (bm << 1) | bb[m][Bm - b - 1];
        Cik[i][k] = quantstep[Bm - 1] * standdev[k - 2] * (bm - Math.pow(2, Bm - 1) + 0.5);
      }
      m++;
    }
  }

  // inverse DCT each Ci,k → Tl
  let l = 1;
  for (let i = 1; i <= 6; i++) {
    const ji = ImbeJi[L9 * 6 + i - 1];
    for (j = 1; j <= ji; j++) {
      let sum = 0;
      for (k = 1; k <= ji; k++) {
        const ak = k === 1 ? 1 : 2;
        sum += ak * Cik[i][k] * Math.cos((Math.PI * (k - 1) * (j - 0.5)) / ji);
      }
      Tl[l] = sum;
      l++;
    }
  }

  // log2Ml from ci,j and the previous frame's log2Ml
  const rho = cur.L <= 15 ? 0.4 : cur.L <= 24 ? 0.03 * cur.L - 0.05 : 0.7;
  if (cur.L > prev.L) {
    for (l = prev.L + 1; l <= cur.L; l++) {
      prev.Ml[l] = prev.Ml[prev.L];
      prev.log2Ml[l] = prev.log2Ml[prev.L];
    }
  }
  let Sum77 = 0;
  for (l = 1; l <= cur.L; l++) {
    flokl[l] = (prev.L / cur.L) * l; // eq. 75
    intkl[l] = Math.trunc(flokl[l]);
    deltal[l] = flokl[l] - intkl[l]; // eq. 76
    Sum77 += (1 - deltal[l]) * prev.log2Ml[intkl[l]] + deltal[l] * prev.log2Ml[intkl[l] + 1]; // eq. 77
  }
  Sum77 = (rho / cur.L) * Sum77;
  for (l = 1; l <= cur.L; l++) {
    const c1 = rho * (1 - deltal[l]) * prev.log2Ml[intkl[l]];
    const c2 = rho * deltal[l] * prev.log2Ml[intkl[l] + 1];
    cur.log2Ml[l] = Tl[l] + c1 + c2 - Sum77;
    cur.Ml[l] = Math.pow(2, cur.log2Ml[l]);
  }
  return 0;
}

// ── AMBE+2 3600x2450 (P25 Phase 2) ───────────────────────────────────────────

/** 0 = voice, 2 = erasure frame, 3 = tone frame (mbelib's return codes). */
export function mbe_decodeAmbe2450Parms(ambe_d: ArrayLike<number>, cur: MbeParms, prev: MbeParms): number {
  const Cik: Float64Array[] = Array.from({ length: 5 }, () => new Float64Array(18));
  const Gm = new Float64Array(9);
  const Ri = new Float64Array(9);
  const Tl = new Float64Array(NL);
  const flokl = new Float64Array(NL);
  const deltal = new Float64Array(NL);
  const intkl = new Int32Array(NL);
  const Ji = new Int32Array(5);
  let silence = 0;
  let f0 = 0;
  let L = 0;

  cur.repeat = prev.repeat;

  const b0 =
    (ambe_d[0] << 6) | (ambe_d[1] << 5) | (ambe_d[2] << 4) | (ambe_d[3] << 3) |
    (ambe_d[37] << 2) | (ambe_d[38] << 1) | ambe_d[39];
  if (b0 >= 120 && b0 <= 123) {
    return 2; // erasure
  } else if (b0 === 124 || b0 === 125) {
    silence = 1;
    cur.w0 = (2 * Math.PI) / 32;
    f0 = 1 / 32;
    L = 14;
    cur.L = 14;
    for (let l = 1; l <= L; l++) cur.Vl[l] = 0;
  } else if (b0 === 126 || b0 === 127) {
    return 3; // tone
  }

  if (silence === 0) {
    f0 = AmbeW0table[b0];
    cur.w0 = f0 * 2 * Math.PI;
  }
  const unvc = 0.2046 / Math.sqrt(cur.w0);
  if (silence === 0) {
    L = Math.trunc(AmbeLtable[b0]);
    cur.L = L;
  }

  // V/UV
  const b1 = (ambe_d[4] << 4) | (ambe_d[5] << 3) | (ambe_d[6] << 2) | (ambe_d[7] << 1) | ambe_d[35];
  for (let l = 1; l <= L; l++) {
    const jl = Math.trunc(l * 16.0 * f0);
    if (silence === 0) cur.Vl[l] = AmbeVuv[b1 * 8 + jl];
  }

  // gain
  const b2 = (ambe_d[8] << 4) | (ambe_d[9] << 3) | (ambe_d[10] << 2) | (ambe_d[11] << 1) | ambe_d[36];
  const deltaGamma = AmbeDg[b2];
  cur.gamma = deltaGamma + 0.5 * prev.gamma;

  // PRBA vectors
  Gm[1] = 0;
  const b3 =
    (ambe_d[12] << 8) | (ambe_d[13] << 7) | (ambe_d[14] << 6) | (ambe_d[15] << 5) | (ambe_d[16] << 4) |
    (ambe_d[17] << 3) | (ambe_d[18] << 2) | (ambe_d[19] << 1) | ambe_d[40];
  Gm[2] = AmbePRBA24[b3 * 3];
  Gm[3] = AmbePRBA24[b3 * 3 + 1];
  Gm[4] = AmbePRBA24[b3 * 3 + 2];
  const b4 =
    (ambe_d[20] << 6) | (ambe_d[21] << 5) | (ambe_d[22] << 4) | (ambe_d[23] << 3) |
    (ambe_d[41] << 2) | (ambe_d[42] << 1) | ambe_d[43];
  Gm[5] = AmbePRBA58[b4 * 4];
  Gm[6] = AmbePRBA58[b4 * 4 + 1];
  Gm[7] = AmbePRBA58[b4 * 4 + 2];
  Gm[8] = AmbePRBA58[b4 * 4 + 3];

  for (let i = 1; i <= 8; i++) {
    let sum = 0;
    for (let m = 1; m <= 8; m++) {
      const am = m === 1 ? 1 : 2;
      sum += am * Gm[m] * Math.cos((Math.PI * (m - 1) * (i - 0.5)) / 8);
    }
    Ri[i] = sum;
  }

  const rconst = 1 / (2 * Math.SQRT2);
  Cik[1][1] = 0.5 * (Ri[1] + Ri[2]);
  Cik[1][2] = rconst * (Ri[1] - Ri[2]);
  Cik[2][1] = 0.5 * (Ri[3] + Ri[4]);
  Cik[2][2] = rconst * (Ri[3] - Ri[4]);
  Cik[3][1] = 0.5 * (Ri[5] + Ri[6]);
  Cik[3][2] = rconst * (Ri[5] - Ri[6]);
  Cik[4][1] = 0.5 * (Ri[7] + Ri[8]);
  Cik[4][2] = rconst * (Ri[7] - Ri[8]);

  // HOC
  const b5 = (ambe_d[24] << 4) | (ambe_d[25] << 3) | (ambe_d[26] << 2) | (ambe_d[27] << 1) | ambe_d[44];
  const b6 = (ambe_d[28] << 3) | (ambe_d[29] << 2) | (ambe_d[30] << 1) | ambe_d[45];
  const b7 = (ambe_d[31] << 3) | (ambe_d[32] << 2) | (ambe_d[33] << 1) | ambe_d[46];
  const b8 = (ambe_d[34] << 2) | (ambe_d[47] << 1) | ambe_d[48];

  for (let i = 0; i < 4; i++) Ji[i + 1] = AmbeLmprbl[L * 4 + i];

  const hoc: [Float32Array, number][] = [
    [AmbeHOCb5, b5],
    [AmbeHOCb6, b6],
    [AmbeHOCb7, b7],
    [AmbeHOCb8, b8],
  ];
  for (let i = 1; i <= 4; i++) {
    const [tbl, bi] = hoc[i - 1];
    for (let k = 3; k <= Ji[i]; k++) {
      Cik[i][k] = k > 6 ? 0 : tbl[bi * 4 + k - 3];
    }
  }

  // inverse DCT each Ci,k → Tl
  let l = 1;
  for (let i = 1; i <= 4; i++) {
    const ji = Ji[i];
    for (let j = 1; j <= ji; j++) {
      let sum = 0;
      for (let k = 1; k <= ji; k++) {
        const ak = k === 1 ? 1 : 2;
        sum += ak * Cik[i][k] * Math.cos((Math.PI * (k - 1) * (j - 0.5)) / ji);
      }
      Tl[l] = sum;
      l++;
    }
  }

  if (cur.L > prev.L) {
    for (l = prev.L + 1; l <= cur.L; l++) {
      prev.Ml[l] = prev.Ml[prev.L];
      prev.log2Ml[l] = prev.log2Ml[prev.L];
    }
  }
  prev.log2Ml[0] = prev.log2Ml[1];
  prev.Ml[0] = prev.Ml[1];

  let Sum43 = 0;
  for (l = 1; l <= cur.L; l++) {
    flokl[l] = (prev.L / cur.L) * l; // eq. 40
    intkl[l] = Math.trunc(flokl[l]);
    deltal[l] = flokl[l] - intkl[l]; // eq. 41
    Sum43 += (1 - deltal[l]) * prev.log2Ml[intkl[l]] + deltal[l] * prev.log2Ml[intkl[l] + 1]; // eq. 43
  }
  Sum43 = (0.65 / cur.L) * Sum43;
  let Sum42 = 0;
  for (l = 1; l <= cur.L; l++) Sum42 += Tl[l];
  Sum42 = Sum42 / cur.L;
  const BigGamma = cur.gamma - 0.5 * (Math.log(cur.L) / Math.log(2)) - Sum42;
  for (l = 1; l <= cur.L; l++) {
    const c1 = 0.65 * (1 - deltal[l]) * prev.log2Ml[intkl[l]];
    const c2 = 0.65 * deltal[l] * prev.log2Ml[intkl[l] + 1];
    cur.log2Ml[l] = Tl[l] + c1 + c2 - Sum43 + BigGamma;
    cur.Ml[l] = cur.Vl[l] === 1 ? Math.exp(0.693 * cur.log2Ml[l]) : unvc * Math.exp(0.693 * cur.log2Ml[l]);
  }
  return 0;
}

/** What happened to one frame — mbelib's err_str, as a code. */
export type MbeFrameKind = "voice" | "repeat" | "muted" | "erasure" | "tone" | "silence";

/** FEC outcome for one IMBE frame: E0 = errors corrected in u0 (Golay, the
 *  pitch and most significant bits), ET = total across c0..c6. `erased`: the
 *  frame is known lost (samples dropped inside it) — conceal it, but it says
 *  nothing about the channel's error rate. A bare number is mbelib's errs2. */
export type ImbeFec = number | { e0: number; et: number; erased?: boolean };

export type MbeProfile = "mbelib" | "enhanced";

/** TIA-102.BABA-A §7.7/§7.8 thresholds, with Trunk Recorder's E0 ≥ 3. */
const MUTE_ER = 0.0875;
const REPEAT_E0 = 3;
const REPEAT_ET_BASE = 10;
const REPEAT_ET_SLOPE = 40;
const MAX_REPEATS = 4;

/**
 * A stateful MBE decoder: one per voice stream (a P25 Phase 1 call, or one
 * Phase 2 timeslot). Holds mbelib's cur / prev / prev_enhanced parameter sets,
 * which carry the spectral prediction and the synthesiser's phase from frame to
 * frame — so frames must be fed in order, and a new call wants `reset()`.
 */
export class MbeDecoder {
  private cur = newMbeParms();
  private prev = newMbeParms();
  private enh = newMbeParms();
  private readonly rand: MbeRng;
  private readonly uvquality: number;
  readonly profile: MbeProfile;
  private readonly synth: MbeSynthOpts | null;
  /** Smoothed channel error rate (TIA ε_R), "enhanced" IMBE only. */
  private er = 0;

  constructor(opts: { rand?: MbeRng; uvquality?: number; profile?: MbeProfile } = {}) {
    this.rand = opts.rand ?? Math.random;
    this.uvquality = opts.uvquality ?? 3;
    this.profile = opts.profile ?? "enhanced";
    this.synth = this.profile === "enhanced" ? ENHANCED_SYNTH : null;
    this.reset();
  }

  /** A clean slate for a new call: parameters, phase, error rate, repeat count. */
  reset(): void {
    mbe_initMbeParms(this.cur, this.prev, this.enh);
    this.er = 0;
  }

  /** Synthesise `cur` against the enhanced previous frame, then advance. */
  private speak(out: Float32Array): void {
    const { cur, prev, enh } = this;
    mbe_moveMbeParms(cur, prev);
    mbe_spectralAmpEnhance(cur);
    mbe_synthesizeSpeechf(out, cur, enh, this.uvquality, this.rand, this.synth);
    mbe_moveMbeParms(cur, enh);
  }

  /**
   * A muted frame that FADES ("enhanced"): a zero-amplitude frame holding the
   * last good pitch, so the previous frame's tail fades out through the
   * synthesis window and the next frame fades in from silence. The
   * prediction memory (`prev`) is left as it was — like a repeat.
   */
  private fadeOut(out: Float32Array): void {
    const { cur, prev, enh } = this;
    mbe_useLastMbeParms(cur, prev);
    for (let l = 0; l <= 56; l++) {
      cur.Ml[l] = 0;
      cur.Vl[l] = 0;
    }
    mbe_synthesizeSpeechf(out, cur, enh, this.uvquality, this.rand, this.synth);
    mbe_moveMbeParms(cur, enh);
    // Keep the pitch/phase/prediction state for the next frame; not the zeros.
    mbe_useLastMbeParms(cur, prev);
  }

  /**
   * One 88-bit IMBE frame (after FEC) → 160 samples, mbelib's float scale.
   * "mbelib": mbe_processImbe4400Dataf exactly (repeat when errs2 > 5, hard
   * silence and a reset past 3 repeats). "enhanced": TIA §7.7/§7.8 with
   * E0 ≥ 3, and fading mutes.
   */
  imbe(imbe_d: ArrayLike<number>, fec: ImbeFec, out = new Float32Array(MBE_FRAME_SAMPLES)): MbeFrameKind {
    const { cur, prev, enh } = this;
    if (this.profile === "mbelib") {
      const errs2 = typeof fec === "number" ? fec : fec.erased ? 99 : fec.et;
      const bad = mbe_decodeImbe4400Parms(imbe_d, cur, prev);
      let kind: MbeFrameKind = "voice";
      if (bad === 1 || errs2 > 5) {
        mbe_useLastMbeParms(cur, prev);
        cur.repeat++;
        kind = "repeat";
      } else {
        cur.repeat = 0;
      }
      if (cur.repeat <= 3) {
        mbe_moveMbeParms(cur, prev);
        mbe_spectralAmpEnhance(cur);
        mbe_synthesizeSpeechf(out, cur, enh, this.uvquality, this.rand);
        mbe_moveMbeParms(cur, enh);
      } else {
        mbe_synthesizeSilencef(out);
        mbe_initMbeParms(cur, prev, enh);
        kind = "muted";
      }
      return kind;
    }

    const f = typeof fec === "number" ? { e0: 0, et: fec, erased: false } : fec;
    // A known-lost frame is concealed but does not count against the channel:
    // otherwise one cut frame's nine erasures would push ε_R over the mute
    // line for half a second of good audio.
    if (!f.erased) this.er = 0.95 * this.er + 0.000365 * f.et;
    if (this.er > MUTE_ER) {
      this.fadeOut(out);
      return "muted";
    }
    const bad = f.erased ? 1 : mbe_decodeImbe4400Parms(imbe_d, cur, prev);
    if (bad === 1 || f.erased || f.e0 >= REPEAT_E0 || f.et >= REPEAT_ET_BASE + REPEAT_ET_SLOPE * this.er) {
      if (prev.repeat >= MAX_REPEATS) {
        this.fadeOut(out);
        return "muted";
      }
      // Repeat: the last good parameters again; the phases still advance.
      mbe_useLastMbeParms(cur, prev);
      cur.repeat = prev.repeat + 1;
      this.speak(out);
      return "repeat";
    }
    cur.repeat = 0;
    this.speak(out);
    return "voice";
  }

  /**
   * One 49-bit AMBE+2 frame (after FEC) → 160 samples. Repeat rules are
   * mbelib's (errs2 > 3 repeats; Trunk Recorder left Phase 2's thresholds
   * alone — they belong to the half-rate FEC). "enhanced" fades where mbelib
   * cuts to silence and resets: past 3 repeats, and on tone/erasure frames.
   */
  ambe(ambe_d: ArrayLike<number>, errs2: number, out = new Float32Array(MBE_FRAME_SAMPLES)): MbeFrameKind {
    const { cur, prev, enh } = this;
    const enhanced = this.profile === "enhanced";
    const bad = mbe_decodeAmbe2450Parms(ambe_d, cur, prev);
    let kind: MbeFrameKind = "voice";
    if (bad === 2) {
      cur.repeat = 0;
      kind = "erasure";
    } else if (bad === 3) {
      cur.repeat = 0;
      kind = "tone";
    } else if (errs2 > 3) {
      mbe_useLastMbeParms(cur, prev);
      cur.repeat++;
      kind = "repeat";
    } else {
      cur.repeat = 0;
    }
    if (bad === 0) {
      if (cur.repeat <= 3) {
        if (enhanced) this.speak(out);
        else {
          mbe_moveMbeParms(cur, prev);
          mbe_spectralAmpEnhance(cur);
          mbe_synthesizeSpeechf(out, cur, enh, this.uvquality, this.rand);
          mbe_moveMbeParms(cur, enh);
        }
      } else if (enhanced) {
        this.fadeOut(out);
        kind = "muted";
      } else {
        mbe_synthesizeSilencef(out);
        mbe_initMbeParms(cur, prev, enh);
        kind = "muted";
      }
    } else if (enhanced) {
      this.fadeOut(out);
    } else {
      mbe_synthesizeSilencef(out);
      mbe_initMbeParms(cur, prev, enh);
    }
    return kind;
  }
}
